#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
	
	int t;
	cin >> t;
	
	while(t--)
	{
	    int n;
	    cin >> n;
	    
	    int a = 3 * n;
	    vector<long long> arr(a);
	    
	    for(int i = 0; i < a; i++)
	    {
	        cin >> arr[i];
	    }
	    
	    sort(arr.rbegin(), arr.rend());
	    
	    vector<long long> pre(a + 1, 0);
	    
	    for(int i = 0; i < a; i++)
	    {
	        pre[i + 1] = pre[i] + arr[i];
	    }
	    
	    long long ans = 0;
	    
	    for(int p = 0; p <= n; p++)
	    {
	        auto total = [&](int q) -> long long
	        {
	            int end3 = a - 2*p - q;
	            
	            return 6 * pre[p] + 4 * (pre[p + 2*q] - pre[p]) + 
	            3 * (pre[end3] - pre[p + 2*q]);
	        };
	        
	        
	        int low = 0, high = n - p;
	        
	        while(low < high)
	        {
	            int mid = low + (high - low) / 2;
	            
	            if(total(mid + 1) > total(mid))
	            {
	                low = mid + 1;
	            }
	            
	            else
	            {
	                high = mid;
	            }
	        }
	        
	        ans = max(ans, total(low));
	    }
	    
	    cout << ans << endl;
	}
    return 0;
}
